using Segusum.Scripting.Core;
namespace Segusum.Translator.Core;
public sealed class DslSourceStringExtractor
{
 public IReadOnlyList<SourceString> Extract(string root,IEnumerable<string>? relativeFiles=null){var files=relativeFiles?.ToArray()??Directory.EnumerateFiles(root,"*.seg",SearchOption.AllDirectories).Where(x=>!x.Split(Path.DirectorySeparatorChar).Any(p=>p is "bin" or "obj" or ".git")).Select(x=>Path.GetRelativePath(root,x)).ToArray();var r=new List<SourceString>();foreach(var rel in files){var path=Path.Combine(root,rel);if(!File.Exists(path))continue;var doc=DslParser.Parse(new DslSource(rel,File.ReadAllText(path))).Document;foreach(var d in doc.Declarations){if(d is FunctionDeclaration f)Walk(f.Body,r,rel);if(d is HandlerDeclaration h)Walk(h.Body,r,rel);if(d is CycleElementDeclaration c)Walk(c.Body,r,rel);} }return r.GroupBy(x=>x.Value,StringComparer.Ordinal).Select(x=>x.First()).ToArray();}
 static void Walk(IEnumerable<DslStatement> body,List<SourceString> r,string path){foreach(var s in body){switch(s){case NarStatement n:Add(r,n.Text,path,n.Span.Line);break;case DialogueStatement d when !d.Character.StartsWith("__",StringComparison.Ordinal):Add(r,d.Text,path,d.Span.Line);break;case IfStatement i:foreach(var b in i.Branches)Walk(b.Body,r,path);if(i.ElseBody!=null)Walk(i.ElseBody,r,path);break;case AddCycleElementStatement a:Walk(a.Body,r,path);break;}}}
 static void Add(List<SourceString> r,DslExpression x,string path,int line){if(x is LiteralExpression l&&l.Kind=="string"){var v=l.Value;v=v.Length>=2&&v[0]=='"'&&v[v.Length-1]=='"'?v.Substring(1,v.Length-2).Replace("\"","''"):v;r.Add(new SourceString(v,path,line));}}
}
